[{"order":1,"type":"heading","text":"Input Validation and Sanitization in JavaScript"},{"order":2,"type":"paragraph","text":"Input validation and sanitization are crucial for building secure and reliable JavaScript applications. They protect against various attacks, such as Cross-Site Scripting (XSS) and SQL injection (if your JavaScript interacts with a database), and ensure data integrity."},{"order":3,"type":"subheading","text":"What is Input Validation?"},{"order":4,"type":"paragraph","text":"Input validation is the process of verifying that user-supplied data conforms to expected formats, types, and values. It ensures that the data meets the application's requirements before it is processed."},{"order":5,"type":"subheading","text":"What is Input Sanitization?"},{"order":6,"type":"paragraph","text":"Input sanitization is the process of modifying user-supplied data to remove or escape potentially harmful characters or code. It aims to prevent malicious code from being executed or stored in the application."},{"order":7,"type":"subheading","text":"Why are Validation and Sanitization Important?"},{"order":8,"type":"bullet_point","text":"Security: Prevents XSS, SQL injection, and other attacks."},{"order":9,"type":"bullet_point","text":"Data Integrity: Ensures data is accurate and consistent."},{"order":10,"type":"bullet_point","text":"Application Stability: Prevents errors and crashes caused by invalid data."},{"order":11,"type":"subheading","text":"Validation Techniques"},{"order":12,"type":"paragraph","text":"Several techniques can be used for input validation in JavaScript:"},{"order":13,"type":"bullet_point","text":"Type Checking: Verify that the data is of the expected type (e.g., string, number, boolean)."},{"order":14,"type":"bullet_point","text":"Format Validation: Ensure that the data matches a specific format (e.g., email address, phone number, date)."},{"order":15,"type":"bullet_point","text":"Range Checking: Verify that the data falls within an acceptable range of values."},{"order":16,"type":"bullet_point","text":"Length Checking: Ensure that the data is within an acceptable length."},{"order":17,"type":"bullet_point","text":"Regular Expressions: Use regular expressions to match patterns and validate complex data formats."},{"order":18,"type":"subheading","text":"Sanitization Techniques"},{"order":19,"type":"paragraph","text":"Common sanitization techniques include:"},{"order":20,"type":"bullet_point","text":"HTML Encoding: Convert special characters (e.g., <, >, &, ") to their corresponding HTML entities."},{"order":21,"type":"bullet_point","text":"URL Encoding: Convert special characters to their URL-encoded equivalents."},{"order":22,"type":"bullet_point","text":"Removing or Escaping Harmful Characters: Remove or escape characters that could be used to inject malicious code."},{"order":23,"type":"subheading","text":"Example: Validating and Sanitizing a Name Field"},{"order":24,"type":"code","text":"// Validation
function isValidName(name) {
  if (typeof name !== 'string') {
    return false;
  }
  if (name.length < 2 || name.length > 50) {
    return false;
  }
  const nameRegex = /^[a-zA-Z\s]+$/;
  return nameRegex.test(name);
}

// Sanitization
function sanitizeName(name) {
  if (typeof name !== 'string') {
    return '';
  }
  return name.trim(); // Remove leading/trailing whitespace
}

const userInput = '  John Doe  ';

if (isValidName(userInput)) {
  const sanitizedName = sanitizeName(userInput);
  console.log('Valid and sanitized name:', sanitizedName);
} else {
  console.log('Invalid name');
}"},{"order":25,"type":"subheading","text":"Example: Validating an Email Address"},{"order":26,"type":"code","text":"function isValidEmail(email) {
  if (typeof email !== 'string') {
    return false;
  }
  const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/;
  return emailRegex.test(email);
}

const emailInput = 'test@example.com';

if (isValidEmail(emailInput)) {
  console.log('Valid email address');
} else {
  console.log('Invalid email address');
}"},{"order":27,"type":"subheading","text":"Best Practices"},{"order":28,"type":"bullet_point","text":"Validate all user inputs, both on the client-side and server-side. Client-side validation provides immediate feedback to the user, while server-side validation is essential for security."},{"order":29,"type":"bullet_point","text":"Use a combination of validation and sanitization techniques to ensure data integrity and security."},{"order":30,"type":"bullet_point","text":"Keep validation and sanitization logic up-to-date to address new security threats."},{"order":31,"type":"bullet_point","text":"Consider using established libraries for validation and sanitization to avoid common pitfalls."},{"order":32,"type":"subheading","text":"Conclusion"},{"order":33,"type":"paragraph","text":"Input validation and sanitization are essential for building secure and reliable JavaScript applications. By implementing these techniques, you can protect your application from various attacks and ensure data integrity."}]
